const created = sdk.operation("northstar.app:operation.custom_receipt_check_create", {
  legalEntityId: event.legalEntityId,
  recordId: event.eventId,
  relations: { "northstar.app:relation.custom_receipt_check_goods_receipt": event.receiptId },
  values: { "northstar.app:field.custom_receipt_check_name": "Receipt check " + event.receiptId }
});
if (created.outcome === "succeeded" && created.readBack !== null) {
  const check = created.readBack;
  const approved = sdk.requestApproval(
    "Mark the receipt check for goods receipt " + event.receiptId + " as Done",
    "northstar.app:operation.custom_receipt_check_action_done",
    { expectedRevision: check.revision, recordId: check.recordId }
  );
  if (approved) {
    sdk.operation("northstar.app:operation.custom_receipt_check_action_done", {
      expectedRevision: check.revision,
      recordId: check.recordId
    });
  }
}

